(() => {
  const orig = window.fetch.bind(window);
  window.fetch = async (input, init) => {
    const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
    if (/\/api\/instances\?fresh=1/.test(url) || /refresh-models/.test(url)) {
      return new Response(JSON.stringify({ error: "The engine's app didn't answer." }), { status: 503, headers: { 'content-type': 'application/json' } });
    }
    const res = await orig(input, init);
    if (/\/api\/instances(\?cached|\?|$)/.test(url) && !/fresh/.test(url)) {
      const body = await res.clone().json().catch(() => null);
      if (!body || !Array.isArray(body.instances)) return res;
      for (const one of body.instances) one.models = { ...one.models, default: '', options: [] };
      return new Response(JSON.stringify(body), { status: res.status, headers: { 'content-type': 'application/json' } });
    }
    return res;
  };
  return true;
})()
